arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Pricing
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalRequest(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalRequest request) => request.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Pricing/S1_GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class S1_GoldCustomerDiscountTests
{
    [Fact]
    public void S1_Gold_customer_with_100_subtotal_pays_95()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalRequest("Gold", 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~S1_" --verbosity quiet 2>&1 | tail -20

